// MPT Paediatrics topics (RGUHS MPT 2020, Papers II-IV, and the paediatric parts of other courses).
// Written in Learn Anywhere's own words. Books are cited by chapter only; nothing is copied.
window.LIB_EXTRA = (window.LIB_EXTRA || []).concat([
{
  id:"nicu-physiotherapy", title:"Physiotherapy in the NICU: the high-risk and preterm neonate", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["NICU","neonatal intensive care","preterm baby physiotherapy","high risk neonate","developmental care","neonatal chest physiotherapy","kangaroo mother care","positioning preterm"],
  simple:"Babies born too early or very sick are cared for in the neonatal intensive care unit. The physiotherapist helps them breathe, lie in good positions, cope with handling and move well, while protecting their fragile brain and lungs. Less is often more: every touch must be gentle, timed with the baby's cues and agreed with the neonatal team.",
  flow:["Read the chart: gestation, corrected age, ventilation, lines, cranial ultrasound, platelets","Watch the baby: stress and stability cues, saturation, heart rate","Position: flexed, midline, contained (nesting) and change position regularly","Respiratory care only when indicated: secretions, collapse; never routine","Support feeding, kangaroo care and parent handling","Plan follow-up: HINE, GMA and developmental surveillance after discharge"],
  exam:[
    {h:"Introduction", p:["A preterm baby is born before 37 completed weeks; very preterm is under 32 weeks and extremely preterm under 28 weeks. Low birth weight is under 2500 g, very low under 1500 g and extremely low under 1000 g.","The NICU physiotherapist works within a neonatal team (neonatologist, nurses, parents) and is a specialist role: training and unit protocols are essential before treating these infants."]},
    {h:"Problems seen in the NICU", p:["Respiratory: respiratory distress syndrome (surfactant deficiency), transient tachypnoea, meconium aspiration, pneumonia, bronchopulmonary dysplasia (oxygen need at 36 weeks corrected age), apnoea of prematurity.","Neurological: intraventricular haemorrhage (graded I-IV), periventricular leukomalacia, hypoxic-ischaemic encephalopathy, neonatal seizures.","Musculoskeletal and positional: flattened 'frog' posture, shoulder retraction, head shape asymmetry (plagiocephaly), torticollis, tight hip abductors.","Others: retinopathy of prematurity, jaundice, necrotising enterocolitis, feeding difficulty."]},
    {h:"Assessment", p:["Chart review: gestational and corrected age, diagnosis, mode of ventilation and FiO2, blood gases, chest X-ray, cranial ultrasound, platelet count and clotting, recent events (apnoea, bradycardia, desaturation).","Observation before touch: behavioural state, colour, breathing pattern and work of breathing (recession, grunting, nasal flaring), posture and spontaneous movement.","Stress cues: colour change, finger splaying, arching, hiccups, yawning, gaze aversion, falling saturation or heart rate. Stability cues: hands to face, flexed posture, sucking, calm alert state.","Neuromotor: tone, quality of general movements, asymmetry; standardised tools after the acute phase (for example TIMP, HINE, Prechtl GMA)."]},
    {h:"Developmental care and positioning", p:["Keep the baby flexed, midline and contained with rolls or nests; hands near mouth; avoid prolonged extension and hip abduction.","Vary positions (supported side lying, prone under monitoring, supine) to protect head shape and joints; prone is used only when monitored in hospital, and families are taught supine sleep at home.","Cluster cares, reduce noise and light, and handle slowly with containment (hands-on 'still' holding).","Encourage skin-to-skin kangaroo mother care, which supports temperature control, breastfeeding, bonding and stability."]},
    {h:"Respiratory physiotherapy: indications and cautions", p:["Not routine. Consider it for retained secretions, lobar collapse after extubation, meconium aspiration or established pneumonia, as agreed with the neonatologist.","Techniques are modified for size: positioning for drainage, gentle chest compression or vibration on expiration, careful suctioning as per unit protocol.","Avoid or take extra care in extremely preterm babies in the first days (risk of intraventricular haemorrhage), low platelets, unstable circulation, rib fragility (osteopenia of prematurity) and recent surgery.","Monitor saturation and heart rate throughout and stop at once if the baby becomes unstable."]},
    {h:"Discharge and follow-up", p:["Teach parents positioning, tummy time while awake, handling and play that bring hands to midline.","Arrange early detection of cerebral palsy and delay: Prechtl GMA before 5 months corrected age and HINE from 3 months, with neuroimaging, as recommended by international guidance.","Use corrected age for milestones until about 2 years.","Link the family to the district early intervention centre (DEIC) and RBSK follow-up."]},
    {h:"Conclusion", p:["NICU physiotherapy is about protecting, positioning and partnering with parents. Gentle, cue-based care and early structured follow-up give high-risk babies the best developmental start."]}
  ],
  tip:"Draw a preterm baby in a nest: flexed limbs, hands to mouth, midline head, with labels for stress cues (arching, finger splay) and stability cues (hand to face, flexion).",
  evidence:[["Kangaroo mother care","Lower mortality and better stability in low birth weight babies","High"],["Routine chest physiotherapy in ventilated preterm babies","No clear benefit; reserve for specific indications","Moderate"],["GMA plus HINE plus MRI for early CP detection","Can detect high risk of CP before 5-6 months corrected age","High"]],
  evidenceSource:"WHO recommendations on kangaroo mother care; Novak et al. JAMA Pediatrics 2017; Cochrane reviews on neonatal chest physiotherapy",
  outcomes:[["TIMP","Postural and selective control in young infants"],["Prechtl GMA","Fidgety movements at 3-5 months corrected age"],["HINE","Neurological examination 2-24 months"],["NIPS / PIPP","Neonatal pain during procedures"]],
  recent:["WHO 2022 recommendations advise starting kangaroo mother care as soon as possible after birth for babies under 2000 g, including those not yet fully stable."],
  mnemonic:{word:"NEST", items:[["N","Neutral, flexed, midline posture"],["E","Environment calm: light, noise, clustered cares"],["S","Stress cues read before and during handling"],["T","Together with parents: kangaroo care and teaching"]], extra:"Nest the baby, not the problem."},
  example:"A baby born at 29 weeks in a Chennai government NICU lies in a frog posture with shoulders pulled back. The physiotherapist builds a nest, teaches the mother kangaroo care and books HINE and GMA follow-up at 3 months corrected age.",
  flags:["Fall in saturation or heart rate during handling: stop","Platelet count very low or active bleeding","Extremely preterm baby in the first 72 hours: avoid non-essential handling","Rib fractures or osteopenia of prematurity"],
  viva:[["What is corrected age?","Chronological age minus the weeks born early; used for milestones until about 2 years."],["Is chest physiotherapy routine in the NICU?","No. It is used only for a clear indication such as retained secretions or collapse, with the team's agreement."],["Name two stress cues of a preterm baby.","Arching or finger splaying, and colour change or desaturation."]],
  refs:[{b:"rennie",ch:"Respiratory disorders, developmental care and follow-up"},{b:"effgen",ch:"Neonatal intensive care and early intervention"},{b:"campbell",ch:"The special care nursery"},{c:"Novak I, et al. Early, accurate diagnosis and early intervention in cerebral palsy. JAMA Pediatrics. 2017;171(9):897-907.",q:"Novak early accurate diagnosis cerebral palsy 2017"}],
  keywords:"NICU preterm neonate physiotherapy positioning developmental care kangaroo",
  mcq:[["Which is the best first step before handling a preterm baby?",["Start percussion","Observe state and stress cues","Do passive ROM","Prone positioning"],1,"Observation of state, cues and monitors comes before any touch."],["Bronchopulmonary dysplasia is defined by oxygen need at:",["28 weeks","32 weeks","36 weeks corrected age","Term plus 6 months"],2,"BPD is commonly defined as oxygen need at 36 weeks corrected (postmenstrual) age."]]
},
{
  id:"gma-hine", title:"Early detection of cerebral palsy: Prechtl General Movements and HINE", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["general movements assessment","GMA","Prechtl","fidgety movements","HINE","Hammersmith infant neurological examination","early diagnosis cerebral palsy","writhing movements"],
  simple:"Babies make whole-body spontaneous movements called general movements. Watching a short video of them at the right age tells a trained observer whether the brain is likely to be healthy. Combined with a simple neurological exam (HINE) and brain scans, we can spot babies at high risk of cerebral palsy in the first months, when early therapy helps most.",
  flow:["Identify the at-risk infant (preterm, HIE, NICU stay)","Video general movements: writhing (term to 6-9 weeks) and fidgety (3-5 months corrected)","Classify: normal, poor repertoire, cramped synchronised, absent fidgety","Do HINE from 3 months corrected and score","Combine with MRI or cranial ultrasound findings","High risk of CP: start early intervention at once"],
  exam:[
    {h:"Introduction", p:["Cerebral palsy used to be diagnosed at 12-24 months. International guidance now supports an early diagnosis or a 'high risk of CP' label before 6 months corrected age so that intervention starts during the period of greatest neuroplasticity.","The best predictive tools are Prechtl's General Movements Assessment (GMA), the Hammersmith Infant Neurological Examination (HINE) and neuroimaging."]},
    {h:"General movements", p:["General movements are spontaneous, complex movements of the whole body seen from fetal life to about 5 months after term.","Preterm and writhing movements (until about 6-9 weeks post term): small to moderate amplitude, slow to moderate speed, elliptical.","Fidgety movements (about 3-5 months corrected age): continuous small circular movements of neck, trunk and limbs in all directions, seen when the baby is awake and calm.","Abnormal patterns: poor repertoire (monotonous), cramped-synchronised (rigid, all limbs together) and, most important, absent fidgety movements, which strongly predict CP."]},
    {h:"How GMA is done", p:["Record 3-5 minutes (writhing) or about 3-5 minutes awake (fidgety) of the baby lying supine, lightly dressed, calm, with no toys or interaction.","Observers trained and certified in the method rate the video by Gestalt perception, not by counting single movements.","It is non-invasive, cheap and can be done from a parent's phone video, which suits low-resource settings."]},
    {h:"HINE", p:["A standardised neurological examination for infants 2-24 months with 26 items in five areas: cranial nerves, posture, movements, tone and reflexes and reactions.","Optimality score out of 78. At 3-12 months, a score under about 57 (3 months) or under about 40 shows high risk of CP; asymmetry scores add information on unilateral CP.","It also helps predict CP severity and can be repeated to track change."]},
    {h:"Putting it together", p:["Before 5 months corrected: GMA (absent fidgety) plus MRI give the best prediction; HINE adds value.","After 5 months: HINE plus MRI plus developmental assessment (for example DAYC or AIMS).","When the result shows high risk, refer for diagnosis, explain to parents honestly and start early, intensive, task-specific and enriched therapy (for example GAME, CIMT in infants with asymmetry, environmental enrichment)."]},
    {h:"Conclusion", p:["Early detection tools turn waiting into acting. A short video and a structured exam let even a small centre flag high-risk babies months earlier than before."]}
  ],
  tip:"Make a two-column table: GMA (age window, normal, abnormal, predictor) against HINE (age, items, cut-off). Add an arrow 'absent fidgety at 3-5 months = high risk of CP'.",
  evidence:[["Absent fidgety movements","Sensitivity about 98 percent and specificity about 91 percent for CP","High"],["HINE score at 3-12 months","Strong predictor of CP and of its severity","High"],["Early intervention after high-risk diagnosis","Better motor and cognitive outcomes when started early and task-specific","Moderate"]],
  evidenceSource:"Novak et al. JAMA Pediatrics 2017; Bosanquet et al. Dev Med Child Neurol 2013; Romeo et al. Dev Med Child Neurol 2016",
  outcomes:[["Prechtl GMA","Writhing and fidgety movement quality"],["HINE","Optimality and asymmetry scores 2-24 months"],["AIMS","Gross motor maturation 0-18 months"],["DAYC-2","Developmental domains 0-5 years"]],
  recent:["Mobile apps and parent-recorded videos for GMA are being validated, helping rural families get screened without travel."],
  mnemonic:{word:"FAM", items:[["F","Fidgety movements at 3-5 months"],["A","Assessment with HINE"],["M","MRI or cranial ultrasound"]], extra:"FAM finds CP early."},
  example:"A 14-week-old baby (corrected age 12 weeks) who had HIE at birth shows no fidgety movements on a phone video and scores 48 on HINE. The team labels 'high risk of CP' and starts GAME-style home programme with the parents.",
  flags:["Absent fidgety movements at 3-5 months corrected","Cramped-synchronised general movements","Persistent asymmetry of hand use before 12 months","Regression of skills: refer urgently"],
  viva:[["What is the age window for fidgety movements?","About 3 to 5 months corrected age."],["What is the maximum HINE score?","78."],["Why diagnose CP early?","To start intervention while neuroplasticity is greatest and to support families sooner."]],
  refs:[{b:"rennie",ch:"Neurological follow-up of high-risk infants"},{b:"effgen",ch:"Early intervention"},{b:"campbell",ch:"Cerebral palsy"},{c:"Novak I, et al. Early, accurate diagnosis and early intervention in cerebral palsy. JAMA Pediatrics. 2017;171(9):897-907.",q:"Novak early diagnosis cerebral palsy JAMA Pediatrics 2017"}],
  keywords:"general movements GMA Prechtl HINE early detection cerebral palsy",
  mcq:[["Which GMA finding most strongly predicts CP?",["Normal writhing","Poor repertoire at 2 weeks","Absent fidgety movements","Startles"],2,"Absent fidgety movements at 3-5 months corrected age are the strongest predictor."],["HINE is used from:",["Birth only","2 to 24 months","5 to 10 years","Adolescence"],1,"HINE is standardised for infants aged 2-24 months."]]
},
{
  id:"gallahue-motor-development", title:"Phases of motor development and fundamental movement skills", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["Gallahue","hourglass model","fundamental movement skills","FMS","phases of motor development","reflexive phase","rudimentary phase","specialised movement phase","motor development across lifespan"],
  simple:"Movement grows in stages. Babies start with reflexes, then learn basic controls like sitting and walking, then the fundamental skills of running, jumping, throwing and catching, and finally use these in sport and daily life. Children do not get good at fundamental skills just by growing older; they need practice, teaching and chances to play.",
  flow:["Reflexive phase: birth to about 1 year","Rudimentary phase: birth to about 2 years","Fundamental phase: 2 to 7 years (initial, emerging, proficient)","Specialised phase: 7 years onwards (transitional, application, lifelong use)","Assess FMS with process and product measures","Teach and practise in rich environments"],
  exam:[
    {h:"Introduction", p:["Motor development is the progressive change in movement behaviour across the lifespan, shaped by the task, the individual (biology) and the environment.","Gallahue's 'hourglass' model shows phases filling up over time, with heredity and environment both pouring into the glass, and later life as an inverted hourglass where skills can be kept or lost."]},
    {h:"The four phases", p:["Reflexive movement phase (in utero to about 1 year): information-encoding then information-decoding stages; primitive and postural reflexes gather information and protect the baby.","Rudimentary movement phase (birth to about 2 years): reflex inhibition then pre-control stages; head and trunk control, reaching and grasping, crawling and walking.","Fundamental movement phase (about 2-7 years): stability (balance, twisting), locomotor (run, jump, hop, gallop, skip) and manipulative (throw, catch, kick, strike) skills, each moving through initial, emerging and proficient stages.","Specialised movement phase (about 7 years onwards): transitional, application and lifelong utilisation stages, where fundamental skills are combined and refined for sport, work and leisure."]},
    {h:"Fundamental movement skills: why they matter", p:["Proficient FMS by about 7 years is linked with higher physical activity, fitness and healthy weight in later childhood and adolescence.","Many children never reach the proficient stage without instruction; maturation alone is not enough.","Poor FMS can be an early sign of developmental coordination disorder or other conditions and calls for assessment."]},
    {h:"Assessment", p:["Process (how the movement looks): TGMD-3 (Test of Gross Motor Development) scores performance criteria of locomotor and ball skills in 3-10 year olds.","Product (outcome): distance jumped, time to run, number of catches.","Broader motor tests: Peabody Developmental Motor Scales (PDMS-2), Movement ABC-2, BOT-2."]},
    {h:"Physiotherapy and teaching implications", p:["Use developmentally appropriate tasks, modify equipment (bigger, lighter, softer balls), give demonstrations, short cues and plenty of practice with feedback.","Provide varied environments (playgrounds, school games) and family involvement.","For children with disability, adapt the task rather than exclude the child."]},
    {h:"Conclusion", p:["Gallahue's phases give the physiotherapist a map from reflexes to sport. Teaching fundamental skills in early childhood builds a base for lifelong physical activity."]}
  ],
  tip:"Draw the hourglass with four layers labelled reflexive, rudimentary, fundamental (stability, locomotor, manipulative) and specialised, with arrows from 'heredity' and 'environment' pouring in.",
  evidence:[["FMS programmes in preschool and school","Improve FMS proficiency compared with free play alone","Moderate"],["FMS competence in childhood","Associated with later physical activity and fitness","Moderate"]],
  evidenceSource:"Logan et al. Child Care Health Dev 2012; Lubans et al. Sports Med 2010; Gallahue, Ozmun and Goodway, Understanding Motor Development",
  outcomes:[["TGMD-3","Locomotor and ball skills, process-oriented"],["PDMS-2","Gross and fine motor 0-5 years"],["MABC-2","Motor impairment screening 3-16 years"]],
  recent:["Many national curricula now include FMS teaching in the early school years as part of physical literacy."],
  mnemonic:{word:"RRFS", items:[["R","Reflexive"],["R","Rudimentary"],["F","Fundamental"],["S","Specialised"]], extra:"Really Rapid Feet Score."},
  example:"A 6-year-old in Coimbatore throws with the same-side foot forward and no trunk rotation (initial stage). The physiotherapist uses targets, a lighter ball and the cue 'step with the opposite foot'.",
  flags:["Loss of skills already gained","Marked asymmetry","Fundamental skills far below peers with daily-life impact (consider DCD)"],
  viva:[["Name the three categories of fundamental movement skills.","Stability, locomotor and manipulative."],["At what age is the fundamental phase?","About 2 to 7 years."],["Does maturation alone produce proficient FMS?","No; instruction and practice are needed."]],
  refs:[{b:"gallahue",ch:"Phases of motor development; fundamental movement skills"},{b:"effgen",ch:"Child development"},{b:"illingworth",ch:"Motor development"}],
  keywords:"Gallahue motor development phases fundamental movement skills hourglass TGMD",
  mcq:[["Hopping and skipping are examples of:",["Manipulative skills","Locomotor skills","Reflexes","Specialised skills"],1,"They move the body through space: locomotor FMS."],["The TGMD-3 measures:",["Fine motor","Locomotor and ball skills","Cognition","Reflexes"],1,"TGMD-3 assesses gross motor locomotor and ball skills."]]
},
{
  id:"paeds-developmental-assessment", title:"Developmental screening and assessment tools in paediatric physiotherapy", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["norm referenced","criterion referenced","AIMS","PDMS-2","GMFM","Bayley","DASII","TDSC","Denver","PEDI","standardised tests paediatrics","psychometric properties"],
  simple:"Screening tests quickly find children who might be behind. Assessment tests look deeper to describe what a child can and cannot do and plan therapy. Some compare a child with other children of the same age (norm-referenced), others check which skills the child has achieved (criterion-referenced). Choose the test that answers your question.",
  flow:["Define the purpose: screen, diagnose, plan or measure change","Pick norm- or criterion-referenced tool for the age","Check reliability, validity and responsiveness","Administer in standard way; use corrected age if preterm","Interpret with the family and the ICF","Re-test to measure progress"],
  exam:[
    {h:"Introduction", p:["Standardised measures make paediatric physiotherapy objective. Each test has a purpose: discriminative (to tell delayed from typical), predictive (to forecast later outcome) or evaluative (to measure change over time).","Norm-referenced tests compare a child with a normative sample and give standard scores or percentiles. Criterion-referenced tests compare with a set standard of skill mastery and are better at showing change."]},
    {h:"Screening tools", p:["Trivandrum Developmental Screening Chart (TDSC, 0-2 and 0-6 years): quick Indian screening chart.","Denver II: screening across personal-social, fine motor, language and gross motor (0-6 years).","Ages and Stages Questionnaires: parent-completed.","Developmental Assessment for Indian Infants (DASII, 0-30 months): Indian adaptation of the Bayley, gives motor and mental DQ."]},
    {h:"Motor assessment tools", p:["Alberta Infant Motor Scale (AIMS, 0-18 months): observational, norm-referenced, prone, supine, sitting and standing items.","Peabody Developmental Motor Scales (PDMS-2, 0-5 years): gross and fine motor quotients.","Gross Motor Function Measure (GMFM-66/88): criterion-referenced, evaluative, for CP and Down syndrome.","Bayley Scales of Infant and Toddler Development: cognitive, language and motor (1-42 months).","Movement ABC-2 and BOT-2: school-age coordination.","PEDI-CAT: daily activities, mobility, social and responsibility domains."]},
    {h:"Psychometric properties", p:["Reliability: test-retest, inter-rater and intra-rater (ICC above about 0.75 is good).","Validity: content, construct, criterion (concurrent and predictive).","Responsiveness: ability to detect real change; minimal clinically important difference (MCID).","Sensitivity and specificity for screening tools; cultural fit and Indian norms where available."]},
    {h:"Practical points", p:["Use corrected age for preterm children up to about 2 years.","Test when the child is well, fed and rested, with a parent present.","Report scores with the meaning in plain language and link findings to ICF activity and participation goals."]},
    {h:"Conclusion", p:["The right test, used the right way, turns observation into evidence. Match the tool to the question: screen, describe, predict or measure change."]}
  ],
  tip:"Make a table with columns: tool, age range, type (norm or criterion), purpose (screen, discriminate, evaluate). Fill AIMS, PDMS-2, GMFM, Bayley, DASII, TDSC, MABC-2.",
  evidence:[["GMFM-66","Valid and responsive measure of gross motor change in CP","High"],["AIMS","Good concurrent validity with Bayley motor scale in infants","Moderate"],["TDSC","Simple, valid screening tool in Indian settings","Moderate"]],
  evidenceSource:"Russell et al. GMFM manual; Darrah et al. AIMS studies; Nair et al. TDSC validation, Indian Pediatrics",
  outcomes:[["AIMS","0-18 months gross motor"],["PDMS-2","0-5 years motor quotients"],["GMFM-66","Gross motor function in CP"],["PEDI-CAT","Functional performance"]],
  recent:["Computer-adaptive tests such as PEDI-CAT shorten testing time while keeping accuracy."],
  mnemonic:{word:"SNAP", items:[["S","Screen or assess? decide purpose"],["N","Norm or criterion referenced"],["A","Age range fits"],["P","Psychometrics: reliable, valid, responsive"]], extra:"SNAP the right test."},
  example:"A 10-month-old born at 30 weeks (corrected 8 months) is screened with TDSC, then assessed with AIMS, scoring at the 5th percentile. Goals are set for sitting and transitions and AIMS is repeated after 3 months.",
  flags:["Regression of skills","Marked asymmetry","Score below 5th percentile with parent concern"],
  viva:[["Difference between norm- and criterion-referenced tests?","Norm compares with peers of same age; criterion compares with a fixed standard of skill."],["Which test is best for measuring change in CP gross motor function?","GMFM-66."],["What is corrected age used for?","Interpreting development of preterm babies up to about 2 years."]],
  refs:[{b:"effgen",ch:"Examination and evaluation; tests and measures"},{b:"campbell",ch:"Measurement in paediatric physical therapy"},{b:"illingworth",ch:"Developmental assessment and diagnosis"},{b:"iap",ch:"Growth and development"}],
  keywords:"developmental assessment screening tools AIMS PDMS GMFM Bayley DASII TDSC psychometric",
  mcq:[["Which is criterion-referenced and evaluative?",["AIMS","GMFM-66","Denver II","TDSC"],1,"GMFM is criterion-referenced and designed to measure change."],["DASII is the Indian adaptation of:",["Denver","Bayley","Peabody","Griffiths"],1,"DASII adapts the Bayley Scales for Indian infants."]]
},
{
  id:"paeds-exercise-physiology", title:"Paediatric exercise physiology: how children respond and adapt to exercise", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["children exercise physiology","aerobic fitness children","peak VO2 children","trainability","maturation","thermoregulation children","anaerobic children","youth fitness"],
  simple:"Children are not small adults. Their hearts, lungs and muscles respond to exercise in their own way: they breathe faster, recover quickly from short bursts, rely more on aerobic energy and handle heat a little differently. They can get fitter and stronger with training, and growth and puberty change these responses.",
  flow:["Know growth and maturation (biological vs chronological age)","Aerobic: peak VO2 rises with size; express relative to body size","Anaerobic: lower in children, faster recovery","Cardio-respiratory: higher HR, smaller stroke volume, higher breathing frequency","Thermoregulation: drink and rest in heat","Training: trainable at all ages, prescribe safely"],
  exam:[
    {h:"Introduction", p:["Exercise responses change with growth (size), maturation (biological timing such as puberty) and development (skills).","Biological age is judged by skeletal age, sexual maturity (Tanner stages) or somatic markers such as peak height velocity, and can differ from chronological age by years."]},
    {h:"Aerobic responses", p:["Peak oxygen uptake (peak VO2) rises with age and body size in both sexes; boys' values rise more around puberty because of muscle mass and haemoglobin.","Children usually reach a peak, not a true plateau, so 'peak VO2' is used. Values should be scaled for body size (allometric scaling is better than simple per-kg).","At the same work rate, children have a higher heart rate and smaller stroke volume; cardiac output is slightly lower; breathing frequency is higher and ventilation less economical.","Oxygen uptake kinetics are faster at the start of exercise, so children reach steady state sooner."]},
    {h:"Anaerobic responses and recovery", p:["Absolute and relative anaerobic power and capacity are lower than in adults (smaller muscle mass, lower glycolytic activity).","Children fatigue less in repeated short sprints and recover faster, so short intermittent play suits them well.","Blood lactate after maximal exercise is lower than in adults."]},
    {h:"Thermoregulation and hydration", p:["Children have a larger surface area to mass ratio and sweat less; they can acclimatise but need more time.","Current evidence suggests healthy children tolerate heat similarly to adults when well hydrated, but rules still matter: shade, scheduled drinks, shorter sessions and lighter clothing, especially in Indian summers."]},
    {h:"Trainability and prescription", p:["Aerobic training improves peak VO2 modestly in children, more after puberty; intensity matters more than volume.","Resistance training increases strength mainly through neural adaptation before puberty; it is safe with supervision and good technique.","WHO recommends an average of 60 minutes a day of moderate to vigorous activity for 5-17 year olds, with vigorous and muscle- and bone-strengthening activity at least 3 days a week.","For children with chronic conditions (asthma, CP, obesity, congenital heart disease) adapt the dose, monitor and progress slowly."]},
    {h:"Conclusion", p:["Understanding paediatric exercise physiology lets the physiotherapist test fairly, interpret results by maturity and prescribe activity that is safe, fun and effective."]}
  ],
  tip:"Draw a comparison table child vs adult: HR (higher), SV (lower), breathing frequency (higher), lactate (lower), recovery (faster), sweating (less).",
  evidence:[["Aerobic training in children","Small to moderate increase in peak VO2","Moderate"],["Supervised resistance training in youth","Improves strength with low injury risk","High"]],
  evidenceSource:"Armstrong and van Mechelen, Oxford Textbook of Children's Sport and Exercise Medicine; WHO 2020 guidelines on physical activity; Lesinski et al. Br J Sports Med 2016",
  outcomes:[["Cycle or treadmill peak VO2","Aerobic fitness"],["20 m shuttle run","Field aerobic fitness"],["Wingate test","Anaerobic power"],["6-minute walk test","Functional capacity in chronic disease"]],
  recent:["WHO 2020 guidelines dropped the minimum 10-minute bout rule: all activity counts, and screen time should be limited."],
  mnemonic:{word:"FAST HEART", items:[["FAST","Faster VO2 kinetics and recovery"],["HEART","Higher heart rate, smaller stroke volume"]], extra:"Kids are fast-starting, quick-recovering engines."},
  example:"A 12-year-old with mild asthma in Madurai is given a running programme with interval play, a warm-up, inhaler before exercise as prescribed and a drink break every 15 minutes in the afternoon heat.",
  flags:["Exercise-induced chest pain or syncope (refer: cardiac cause)","Breathlessness out of proportion to effort","Signs of heat illness: confusion, vomiting, stopped sweating"],
  viva:[["Why use peak VO2 rather than VO2 max in children?","Children often do not show a plateau at exhaustion."],["How does strength increase before puberty?","Mainly through neural adaptations."],["WHO activity recommendation for children?","Average 60 minutes per day of moderate to vigorous activity."]],
  refs:[{b:"armstrong",ch:"Aerobic and anaerobic fitness; trainability; thermoregulation"},{b:"effgen",ch:"Fitness and physical activity"},{b:"acsm",ch:"Children and adolescents"}],
  keywords:"paediatric exercise physiology children peak VO2 trainability thermoregulation maturation",
  mcq:[["Compared with adults, children at the same submaximal workload have:",["Lower heart rate","Higher heart rate","Higher stroke volume","Higher lactate"],1,"Higher HR compensates for smaller stroke volume."],["Strength gains in prepubertal children are mainly due to:",["Hypertrophy","Neural adaptation","Hormones","Bone growth"],1,"Neural adaptation dominates before puberty."]]
},
{
  id:"youth-resistance-training", title:"Exercise prescription and strength training in children and adolescents", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["exercise prescription adolescents","youth strength training","resistance training children","long term athletic development","children fitness programme","adolescent exercise"],
  simple:"Children and teenagers can safely get stronger and fitter when training is supervised, technique comes first and the load grows slowly. A good plan mixes play, fundamental skills, strength, balance and aerobic work, and fits the child's maturity, not just age.",
  flow:["Screen health and readiness (PAR-Q style, history)","Teach technique with light load first","Prescribe 2-3 sessions a week, 1-3 sets of 6-15 reps","Progress load by about 5-10 percent when technique is good","Include warm-up, FMS, balance, aerobic and rest days","Monitor growth spurts, pain and enjoyment"],
  exam:[
    {h:"Introduction", p:["Youth resistance training is a planned programme using body weight, bands, free weights or machines to improve strength, power and muscular endurance.","Major sports medicine bodies agree it is safe and beneficial when supervised and age appropriate; children can start when they can follow instructions (often around 7-8 years)."]},
    {h:"Benefits", p:["Strength, power, motor skill and sports performance.","Bone mineral density, especially around puberty.","Reduced sports injury risk when combined with neuromuscular training.","Better body composition, insulin sensitivity, self-esteem and lifelong activity habits."]},
    {h:"Prescription (FITT)", p:["Frequency: 2-3 non-consecutive days a week.","Intensity: start light, 1-2 sets of 10-15 reps; progress to 1-3 sets of 6-12 reps at moderate load; heavy maximal lifts only after long experience and technique mastery.","Time: 20-60 minutes including warm-up and cool-down.","Type: multi-joint movements (squat, lunge, push, pull), core and balance, plyometrics at low volume; aerobic play and games on other days.","Progression: increase load by about 5-10 percent when all reps are done with good form."]},
    {h:"Safety and special points", p:["Qualified supervision, a ratio of about 1 adult to 10 children, safe equipment and environment.","During the adolescent growth spurt reduce load and impact if pain appears (risk of apophysitis such as Osgood-Schlatter or Sever's disease).","Avoid early single-sport specialisation; follow long-term athletic development ideas.","For children with disabilities (CP, Down syndrome, obesity) the same principles apply with adapted exercises and closer monitoring."]},
    {h:"Conclusion", p:["Strength training is a safe, valuable part of a child's physical activity when technique, supervision and gradual progression come first."]}
  ],
  tip:"Write a sample weekly plan for a 13-year-old: Mon strength (squats, push-ups, rows, plank), Wed games and aerobic, Fri strength plus balance, weekend free play.",
  evidence:[["Supervised youth resistance training","Improves strength and motor skills with low injury rates","High"],["Neuromuscular training programmes","Reduce lower limb injury in youth athletes","High"],["Resistance training in children with CP","Improves strength; transfer to function is less certain","Moderate"]],
  evidenceSource:"Lloyd et al. Br J Sports Med 2014 international consensus; Lesinski et al. Br J Sports Med 2016; Faigenbaum et al. NSCA position statement",
  outcomes:[["Handgrip dynamometry","Strength"],["Standing long jump","Power"],["Push-up and sit-up tests","Muscular endurance"],["Enjoyment scale (PACES)","Enjoyment and adherence"]],
  recent:["International consensus (2014, updated discussions since) supports integrating strength and FMS in physical education from early childhood."],
  mnemonic:{word:"STEP", items:[["S","Supervise"],["T","Technique first"],["E","Enjoyable, varied"],["P","Progress slowly (5-10 percent)"]], extra:"STEP up, not jump up."},
  example:"A 14-year-old hockey player in Bengaluru in a growth spurt has knee pain at the tibial tubercle. Plyometric volume is cut, quadriceps and hip strength work continues pain-free and play time is managed until pain settles.",
  flags:["Pain at growth plates or apophyses during growth spurt","Chest pain or fainting on exertion","Back pain with extension in young athletes (consider spondylolysis)"],
  viva:[["Is resistance training safe for children?","Yes, with qualified supervision, good technique and gradual progression."],["Typical frequency?","2-3 non-consecutive days per week."],["Name an apophysitis seen in growth spurt.","Osgood-Schlatter disease or Sever's disease."]],
  refs:[{b:"armstrong",ch:"Resistance training in youth; long-term athletic development"},{b:"effgen",ch:"Fitness and adolescents"},{b:"acsm",ch:"Exercise prescription for children and adolescents"},{c:"Lloyd RS, et al. Position statement on youth resistance training: the 2014 International Consensus. Br J Sports Med. 2014;48(7):498-505.",q:"Lloyd youth resistance training 2014 international consensus"}],
  keywords:"youth resistance training adolescents exercise prescription children strength",
  mcq:[["Recommended starting reps for a novice child:",["1-3","10-15 at light load","20-30 at heavy load","Maximum lifts"],1,"Start light with higher reps to learn technique."],["Strength training in youth is best done:",["Daily","2-3 non-consecutive days a week","Once a month","Only after 18 years"],1,"2-3 days a week with rest days."]]
},
{
  id:"paeds-bls-pals", title:"Paediatric basic life support and PALS essentials for physiotherapists", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["PALS","paediatric BLS","infant CPR","child CPR","NALS","pediatric advanced life support","choking infant","paediatric resuscitation"],
  simple:"Children usually arrest because breathing fails first, not the heart. So noticing a child who is struggling to breathe or in shock and acting early saves lives. If a child stops responding and is not breathing normally, shout for help, start chest compressions and rescue breaths and use a defibrillator when it arrives. Physiotherapists working with children must be trained and certified.",
  flow:["Check safety, response and breathing (and pulse if trained, under 10 s)","Shout for help, call emergency team, get AED","Start CPR: push hard and fast, allow full recoil","Give breaths: 30:2 alone, 15:2 with two rescuers (child and infant)","Use AED as soon as available, follow prompts","Continue until help takes over; recognise and treat respiratory failure and shock early"],
  exam:[
    {h:"Introduction", p:["Paediatric cardiac arrest is most often secondary to respiratory failure or shock (hypoxia), unlike sudden cardiac arrest in adults. Early recognition of the seriously ill child prevents many arrests.","PALS is an advanced course for health professionals; BLS skills are the foundation. Guidelines are updated regularly (AHA/AAP updated paediatric BLS and PALS in 2025), so always learn from the current official guideline and a certified course."]},
    {h:"Recognising the seriously ill child (PAT)", p:["Paediatric Assessment Triangle: appearance (tone, interaction, consolability, gaze, cry), work of breathing (recessions, nasal flaring, grunting, head bobbing), circulation to skin (pallor, mottling, cyanosis).","Then a systematic ABCDE assessment: airway, breathing (rate, SpO2, effort), circulation (heart rate, capillary refill, BP), disability (AVPU, glucose), exposure.","Know normal ranges: infants breathe and beat faster than older children."]},
    {h:"High-quality CPR for infants and children", p:["Compression rate 100-120 per minute, depth at least one third of the chest's front-to-back diameter (about 4 cm in infants, about 5 cm in children), full recoil and minimal pauses.","Infants: 2025 guidance recommends the two-thumb encircling technique or the heel of one hand; the two-finger technique was removed because it does not give enough depth.","Ratio 30:2 for a single rescuer and 15:2 for two rescuers in infants and children, until an advanced airway is placed.","Use an AED as soon as possible; use paediatric pads or attenuator if available for young children, adult pads if not."]},
    {h:"Choking (foreign body airway obstruction)", p:["Infant: cycles of 5 back blows and 5 chest thrusts; abdominal thrusts are not used in infants.","Child: per 2025 guidance, cycles of 5 back blows alternating with 5 abdominal thrusts.","If the child becomes unresponsive, start CPR and look in the mouth before breaths, removing only a visible object."]},
    {h:"Relevance to physiotherapy", p:["Physiotherapists treat at-risk children in PICU, NICU, wards and schools: during airway clearance or exercise, watch for desaturation, bradycardia and fatigue.","Keep suction, oxygen and bag-valve-mask ready in the treatment area; know the hospital emergency number and the location of the AED and crash cart.","Keep BLS certification current (usually every 2 years) and do PALS or NALS if working in critical care."]},
    {h:"Conclusion", p:["Early recognition, high-quality CPR and fast defibrillation are the core of paediatric resuscitation. Learn the current guideline hands-on and practise regularly."]}
  ],
  tip:"Draw the Paediatric Assessment Triangle (appearance, work of breathing, circulation to skin) and a box with CPR numbers: rate 100-120, depth one third, 30:2 alone, 15:2 two rescuers.",
  evidence:[["High-quality CPR with minimal interruptions","Improves survival","High"],["Two-finger infant compressions","Insufficient depth; removed in 2025 AHA/AAP guidance","Moderate"],["Early recognition systems (paediatric early warning scores)","Help detect deterioration earlier","Moderate"]],
  evidenceSource:"AHA/AAP 2025 Guidelines for Pediatric Basic and Advanced Life Support; Disque, PALS Provider Handbook",
  outcomes:[["Paediatric early warning score (PEWS)","Detection of deterioration"],["AVPU / GCS","Level of consciousness"],["CPR quality feedback","Rate, depth, recoil in training"]],
  recent:["The 2025 AHA/AAP update uses one chain of survival for adults and children, removes the two-finger infant technique and abdominal thrusts in infants, and recommends back blows alternating with abdominal thrusts for choking children."],
  mnemonic:{word:"CAB-D", items:[["C","Compressions hard and fast"],["A","Airway open"],["B","Breaths 30:2 or 15:2"],["D","Defibrillate with AED early"]], extra:"For children, think breathing problems first, but start CPR with compressions."},
  example:"During postural drainage a 3-year-old in PICU becomes limp and stops breathing normally. The physiotherapist calls the code, starts compressions with one hand at one-third chest depth and gives breaths 15:2 with the nurse until the team arrives.",
  flags:["Silent chest, exhaustion or falling respiratory rate in a breathless child","Bradycardia in a hypoxic child","Unresponsive and not breathing normally: start CPR"],
  viva:[["Most common cause of paediatric cardiac arrest?","Respiratory failure or shock leading to hypoxia."],["Compression to ventilation ratio with two rescuers for a child?","15:2."],["Which infant compression technique was removed in 2025?","The two-finger technique."]],
  refs:[{b:"pals",ch:"Systematic approach, BLS and respiratory emergencies"},{b:"iap",ch:"Paediatric emergencies and resuscitation"},{b:"rennie",ch:"Neonatal resuscitation"},{c:"American Heart Association and American Academy of Pediatrics. 2025 Guidelines for Cardiopulmonary Resuscitation and Emergency Cardiovascular Care: Pediatric Basic and Advanced Life Support.",q:"2025 AHA AAP pediatric basic life support guidelines"}],
  checked:"Infant technique, ratios and choking steps checked against the AHA/AAP 2025 paediatric BLS update summary on 31 Oct 2026. Always follow your current certified course.",
  keywords:"paediatric BLS PALS infant CPR choking resuscitation physiotherapy",
  mcq:[["Compression depth in infants is about:",["1 cm","One third of chest depth, about 4 cm","8 cm","Half the chest depth"],1,"At least one third of the AP diameter, about 4 cm."],["For a choking infant, the recommended cycle is:",["Abdominal thrusts","5 back blows and 5 chest thrusts","Blind finger sweep","Only rescue breaths"],1,"Back blows alternating with chest thrusts; no abdominal thrusts in infants."]]
},
{
  id:"down-syndrome-pt", title:"Down syndrome: physiotherapy assessment and management", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["trisomy 21","Down's syndrome","hypotonia","ligamentous laxity","atlantoaxial instability","treadmill training Down syndrome"],
  simple:"Children with Down syndrome are born with an extra chromosome 21. Most have low muscle tone and loose joints, so they reach motor milestones later and move with a wide base. They learn well with practice. Physiotherapy helps them walk earlier, build strength and fitness and join play and school, while watching for heart and neck problems.",
  flow:["Know the medical profile: heart, thyroid, vision, hearing, neck","Assess tone, laxity, milestones, posture and fitness","Early intervention: tummy time, supported sitting, standing","Treadmill and walking practice before independent walking","Strength, balance and fitness through childhood","Participation in sport with screening for neck symptoms"],
  exam:[
    {h:"Introduction", p:["Down syndrome (trisomy 21) is the commonest chromosomal cause of intellectual disability, about 1 in 700-1000 live births; risk rises with maternal age.","Types: free trisomy (about 95 percent), translocation and mosaic."]},
    {h:"Features relevant to physiotherapy", p:["Hypotonia, joint hypermobility and ligamentous laxity; reduced strength and slower postural reactions.","Delayed milestones: sitting around 11 months on average, walking around 2 years (range 13-48 months).","Associated problems: congenital heart disease (about 40-50 percent, especially AVSD), hypothyroidism, obesity, visual and hearing loss, obstructive sleep apnoea, flat feet, patellar instability, scoliosis, hip instability.","Atlantoaxial instability: radiological in about 10-20 percent, symptomatic in about 1-2 percent."]},
    {h:"Assessment", p:["History including heart status and surgery, thyroid, vision, hearing.","Tone, joint range and laxity, posture (wide base, hyperextended knees, flat feet), strength, balance.","Developmental tools: AIMS, PDMS-2, GMFM (has a Down syndrome version), BOT-2 later; fitness tests adapted.","Ask about neck symptoms: neck pain, head tilt, change in gait, weakness, bladder change (urgent referral)."]},
    {h:"Management by age", p:["Infancy: parent-led handling, tummy time, midline play, supported sitting, avoid excessive hip abduction positions.","Pre-walking: treadmill training with support (a few minutes a day, several days a week) has been shown to bring forward independent walking.","Childhood: strength (functional and resistance), balance, coordination, fundamental movement skills; orthoses (supramalleolar or foot orthoses) if foot posture affects function.","Adolescence and adult: aerobic and resistance exercise to manage weight and fitness; Special Olympics and community sport."]},
    {h:"Precautions", p:["Avoid forced neck flexion and high-risk neck activities (somersaults, diving, contact) if instability is suspected or confirmed; follow national sports screening policy.","Check cardiac clearance before vigorous exercise.","Do not over-stretch lax joints; focus on stability and strength."]},
    {h:"Conclusion", p:["With early, family-centred practice and a lifelong active lifestyle, children with Down syndrome can reach their motor potential and participate fully."]}
  ],
  tip:"Draw a child figure with labels: hypotonia, lax joints, hyperextended knees, flat feet, wide base gait, and a note 'check neck, heart, thyroid'.",
  evidence:[["Treadmill training in infants with Down syndrome","Earlier onset of independent walking","Moderate"],["Progressive resistance training in adolescents","Improves muscle strength","Moderate"]],
  evidenceSource:"Ulrich et al. Pediatrics 2001 and 2008; Shields et al. Arch Phys Med Rehabil 2013",
  outcomes:[["GMFM (Down syndrome version)","Gross motor function"],["AIMS / PDMS-2","Motor development"],["6-minute walk test","Endurance"],["Handgrip strength","Strength"]],
  recent:["Health supervision guidelines (AAP 2022) no longer advise routine neck X-rays for all children with Down syndrome; focus is on symptom screening."],
  mnemonic:{word:"HEART", items:[["H","Hypotonia and hypermobility"],["E","Early intervention and treadmill"],["A","Atlantoaxial watch"],["R","Resistance and fitness"],["T","Thyroid, heart, vision, hearing checks"]], extra:"Train with HEART."},
  example:"An 11-month-old girl with Down syndrome in Trichy sits with support. Her mother is taught a daily routine of tummy time, reaching in supported sitting and short supported steps on a home treadmill borrowed through the DEIC.",
  flags:["Neck pain, torticollis, new clumsiness, weakness or bladder change (atlantoaxial instability)","Breathlessness or cyanosis on exertion (cardiac)","Sudden weight gain and lethargy (hypothyroidism)"],
  viva:[["Most common chromosomal pattern in Down syndrome?","Free trisomy 21 (about 95 percent)."],["Which training brings forward walking in infants with Down syndrome?","Supported treadmill stepping."],["Name a spinal precaution.","Watch for atlantoaxial instability; avoid forced neck flexion if suspected."]],
  refs:[{b:"effgen",ch:"Children with Down syndrome; intellectual disability"},{b:"campbell",ch:"Down syndrome"},{b:"iap",ch:"Chromosomal disorders"},{b:"nelson",ch:"Down syndrome"}],
  keywords:"Down syndrome trisomy 21 hypotonia physiotherapy treadmill atlantoaxial",
  mcq:[["Average age of independent walking in Down syndrome:",["10 months","About 2 years","5 years","Never"],1,"About 24 months, with a wide range."],["Main precaution in contact sport:",["Atlantoaxial instability","Hip OA","Plantar fasciitis","Tennis elbow"],0,"Screen for symptoms of atlantoaxial instability."]]
},
{
  id:"dcd", title:"Developmental coordination disorder (DCD)", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["clumsy child","dyspraxia","developmental dyspraxia","CO-OP","neuromotor task training","motor coordination difficulty","MABC-2"],
  simple:"Some children of normal intelligence find everyday movement tasks very hard: handwriting, tying laces, catching, riding a cycle. When this clearly affects school and daily life and no other condition explains it, it is called developmental coordination disorder. Practising real tasks with smart strategies helps more than general exercises.",
  flow:["Notice: clumsiness affecting daily life or school","Diagnose with DSM-5 criteria A-D","Assess: MABC-2, DCDQ, function and participation","Intervene: task-oriented (CO-OP, NTT)","Add fitness and sport participation","Support school: handwriting, PE, extra time"],
  exam:[
    {h:"Introduction", p:["DCD affects about 5-6 percent of school-age children, more boys than girls. It often coexists with ADHD, learning disorders and speech and language disorders.","It was called 'clumsy child syndrome' or dyspraxia in the past."]},
    {h:"Diagnosis (DSM-5 criteria)", p:["A: motor skills well below expected for age and opportunity.","B: the deficit significantly interferes with daily activities, school, leisure or play.","C: onset in the early developmental period.","D: not better explained by intellectual disability, visual impairment or a neurological condition such as CP or muscular dystrophy.","International guidance suggests diagnosing usually after 5 years of age."]},
    {h:"Assessment", p:["Movement ABC-2 (below 16th percentile, with below 5th indicating definite difficulty) or BOT-2 for criterion A.","DCD Questionnaire (parent) and teacher reports for criterion B.","Neurological screen and medical review to rule out other causes (criterion D).","Also assess fitness, handwriting, self-care, participation and self-esteem."]},
    {h:"Intervention", p:["Task-oriented approaches have the best evidence: Cognitive Orientation to daily Occupational Performance (CO-OP) uses goal-plan-do-check problem solving; Neuromotor Task Training (NTT) adjusts task constraints and practice.","Work on the child's own goals (riding a bicycle, catching, writing), with lots of practice in real settings.","Process-oriented methods (sensory integration, perceptual-motor training alone) have weaker evidence.","Promote physical activity and fitness because children with DCD are often less active and more overweight; involve parents and teachers."]},
    {h:"Conclusion", p:["DCD is common and often missed. Early recognition, task-specific practice and school support improve skills, confidence and participation."]}
  ],
  tip:"Draw the CO-OP loop: Goal, Plan, Do, Check, with an example 'tie shoelaces'.",
  evidence:[["Task-oriented interventions (CO-OP, NTT)","Improve motor performance and goal attainment","High"],["Process-oriented approaches alone","Less effective","Moderate"]],
  evidenceSource:"Blank et al. Dev Med Child Neurol 2019 international clinical practice recommendations on DCD; Smits-Engelsman et al. 2018 meta-analysis",
  outcomes:[["MABC-2","Motor performance"],["DCDQ","Parent-reported coordination in daily life"],["COPM / GAS","Goal performance and attainment"],["Handwriting legibility scale","Handwriting"]],
  recent:["The 2019 international DCD recommendations stress task-oriented, activity and participation focused therapy and caution against diagnosing before age 5."],
  mnemonic:{word:"GPDC", items:[["G","Goal"],["P","Plan"],["D","Do"],["C","Check"]], extra:"CO-OP: Good Plans Do Count."},
  example:"An 8-year-old boy in Salem cannot ride a bicycle and avoids PE. MABC-2 total is at the 2nd percentile. Using CO-OP he sets the goal 'ride to school' and, with practice and strategies, rides independently in 8 sessions.",
  flags:["Loss of skills or progressive weakness (consider neuromuscular disease)","Focal neurological signs","Severe anxiety or bullying related to motor difficulty"],
  viva:[["Prevalence of DCD?","About 5-6 percent of school-age children."],["Best evidence-based approach?","Task-oriented interventions such as CO-OP and NTT."],["Name a tool for criterion A.","Movement ABC-2."]],
  refs:[{b:"effgen",ch:"Developmental coordination disorder"},{b:"gallahue",ch:"Motor development difficulties"},{b:"campbell",ch:"Developmental coordination disorder"},{c:"Blank R, et al. International clinical practice recommendations on the definition, diagnosis, assessment, intervention, and psychosocial aspects of developmental coordination disorder. Dev Med Child Neurol. 2019;61(3):242-285.",q:"Blank 2019 developmental coordination disorder recommendations"}],
  keywords:"developmental coordination disorder DCD dyspraxia CO-OP MABC-2",
  mcq:[["DCD diagnosis usually made after age:",["1 year","2 years","5 years","12 years"],2,"Recommendations advise diagnosis usually after 5 years."],["CO-OP stands for:",["Cognitive Orientation to daily Occupational Performance","Coordinated Orthopaedic Programme","Child Outcome Plan","Core Postural Training"],0,"CO-OP is a cognitive, task-oriented approach."]]
},
{
  id:"school-based-pt", title:"Role of the paediatric physiotherapist in mainstream, inclusive and special schools", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["school physiotherapy","inclusive education","special school","integrated school","RPwD Act education","school based services","ergonomics in school children","school bag"],
  simple:"Children spend much of their day at school. A physiotherapist in school helps children with disabilities move, sit, play and learn alongside others, trains teachers, adapts the classroom and playground and promotes health for all children, such as safe school bags and active play.",
  flow:["Understand the school and the law (inclusive education)","Assess the child in the school setting","Set educationally relevant goals with teachers and parents","Choose service model: direct, integrated, consultative","Adapt environment, seating and equipment","Train staff; review progress each term"],
  exam:[
    {h:"Introduction", p:["Settings: mainstream schools, inclusive (integrated) schools where children with disabilities learn with peers, and special schools.","In India the Rights of Persons with Disabilities Act 2016 and Samagra Shiksha support inclusive education, and RBSK screens school children for defects, diseases, deficiencies and developmental delays."]},
    {h:"Roles", p:["Assessment of mobility, posture, seating, access, self-care and participation in class, playground and PE.","Goals linked to the child's education plan (IEP): getting to the toilet independently, sitting to write, joining PE.","Direct therapy when needed, but mainly integrated therapy within routines and consultation with teachers.","Adaptive equipment: chairs and tables of correct height, standing frames, walkers, wheelchairs, ramps and rails.","Health promotion for all children: posture, school bag weight (commonly advised under about 10 percent of body weight), active breaks, fitness and injury prevention.","Training teachers and caregivers in safe handling and transfers."]},
    {h:"Service delivery models", p:["Direct (pull-out or in-class) therapy.","Integrated therapy: practice embedded in classroom routines.","Consultative: advising teachers and parents who carry out the programme.","Collaborative team model with special educators, OT, speech therapist and parents; transdisciplinary approach is common in early years."]},
    {h:"Ergonomic assessment in schools", p:["Match furniture to anthropometry: seat height near popliteal height, desk height near elbow height when seated.","Check screens, lighting and how long children sit; plan movement breaks.","Assess bag carrying: both straps, heavy items close to the back."]},
    {h:"Conclusion", p:["The school physiotherapist helps every child, with or without disability, take part in learning and play. Working with teachers is as important as working with the child."]}
  ],
  tip:"Draw a classroom: correct chair and desk heights, a ramp at the door, a child with a walker and a teacher being trained, labelled 'integrated therapy'.",
  evidence:[["Integrated, routine-based therapy","At least as effective as pull-out therapy for functional school goals","Moderate"],["Furniture matched to anthropometry","Better posture and less musculoskeletal discomfort","Moderate"]],
  evidenceSource:"Effgen, Meeting the Physical Therapy Needs of Children; Castellucci et al. Appl Ergon reviews on school furniture",
  outcomes:[["School Function Assessment (SFA)","Participation and task supports at school"],["GAS","Individual school goals"],["PEDI-CAT","Daily activities"]],
  recent:["The National Education Policy 2020 promotes inclusion and school health and wellness programmes."],
  mnemonic:{word:"SCHOOL", items:[["S","Seating and posture"],["C","Collaborate with teachers"],["H","Health promotion"],["O","Outdoor play and PE access"],["O","Orthoses and equipment"],["L","Law: RPwD Act, inclusion"]], extra:"Therapy goes to SCHOOL."},
  example:"A 9-year-old with diplegic CP in a Madurai government school cannot reach the toilet in time. The physiotherapist adds a rail, trains the class assistant, practises the route daily with the child and the teacher records independence each week.",
  flags:["Child excluded from PE or play","Pain from poor seating or heavy bags","Unsafe transfers by untrained staff"],
  viva:[["Name three service delivery models.","Direct, integrated and consultative."],["Which Indian act supports inclusive education?","Rights of Persons with Disabilities Act 2016."],["What is integrated therapy?","Therapy practised inside the child's daily school routines."]],
  refs:[{b:"effgen",ch:"Service delivery in schools; inclusive education"},{b:"campbell",ch:"The educational environment"}],
  keywords:"school physiotherapy inclusive education special school service delivery ergonomics",
  mcq:[["In the consultative model the therapist mainly:",["Treats daily","Advises teachers and parents","Does surgery","Only screens"],1,"Consultation supports those who carry out the programme."],["Ideal desk height for seated children is close to:",["Shoulder height","Elbow height","Knee height","Eye level"],1,"Desk near seated elbow height."]]
},
{
  id:"paeds-pain", title:"Pain assessment and management in neonates and children", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["neonatal pain","PIPP","NIPS","FLACC","Wong-Baker","faces pain scale","sucrose","non-pharmacological pain relief children","paediatric pain scales"],
  simple:"Even tiny babies feel pain, and untreated pain can harm the developing brain. Babies and young children cannot tell us in words, so we look at their face, cry, body and vital signs using scales made for their age. Simple comforts like holding, breastfeeding, swaddling and distraction work well alongside medicines.",
  flow:["Believe that babies and children feel pain","Pick an age-suitable scale (behavioural or self-report)","Assess before, during and after procedures","Use non-drug methods: skin-to-skin, breastfeeding, sucrose, distraction","Work with the team on medicines","Reassess and document"],
  exam:[
    {h:"Introduction", p:["Pain pathways are functional from about mid-gestation; preterm babies may be more sensitive because descending inhibition is immature.","Repeated untreated pain in early life is linked with altered pain sensitivity and neurodevelopment, so assessment and prevention matter."]},
    {h:"Assessment tools by age", p:["Neonates: PIPP-R (Premature Infant Pain Profile, includes gestational age and behavioural state), NIPS (Neonatal Infant Pain Scale), N-PASS.","Infants and young children (behavioural): FLACC (Face, Legs, Activity, Cry, Consolability, 0-10).","From about 4 years: Faces Pain Scale-Revised; Wong-Baker FACES; from about 8 years: numeric rating scale or VAS.","Children with cognitive impairment: revised FLACC or non-communicating children's pain checklist; parents' knowledge of the child's cues is vital."]},
    {h:"Non-pharmacological management", p:["Neonates: skin-to-skin (kangaroo) care, breastfeeding during the procedure, oral sucrose or glucose (as per unit protocol), non-nutritive sucking, swaddling and facilitated tucking.","Children: preparation and honest explanation, distraction (bubbles, toys, videos, stories), relaxation and breathing, positioning, parents' presence, heat or cold where safe, TENS in older children.","Cognitive-behavioural approaches and graded activity for chronic pain such as juvenile fibromyalgia or recurrent abdominal pain."]},
    {h:"Pharmacological (team role)", p:["Local anaesthetic creams before needles, paracetamol and NSAIDs, opioids for severe pain under medical supervision.","Physiotherapists time treatment to medication peaks for painful procedures such as stretching after burns or post-operative mobilisation."]},
    {h:"Conclusion", p:["Measuring pain with the right scale and combining comfort measures with medicines makes therapy kinder and more effective for children."]}
  ],
  tip:"Draw an age ladder: neonate PIPP-R/NIPS, toddler FLACC, 4-8 years Faces scale, 8+ numeric scale.",
  evidence:[["Breastfeeding or skin-to-skin during neonatal procedures","Reduces pain responses","High"],["Oral sucrose for minor procedures","Reduces behavioural pain scores in neonates","High"],["Distraction in children","Reduces needle pain and distress","High"]],
  evidenceSource:"Cochrane reviews (Shah 2012; Johnston 2017; Stevens 2016; Birnie 2018)",
  outcomes:[["PIPP-R","Neonatal procedural pain"],["FLACC","Behavioural pain 2 months-7 years"],["FPS-R","Self-report 4-12 years"],["NRS","Self-report 8 years and above"]],
  recent:["WHO 2020 guidelines on chronic pain in children emphasise physical therapy and psychological therapy together with careful medicine use."],
  mnemonic:{word:"FLACC", items:[["F","Face"],["L","Legs"],["A","Activity"],["C","Cry"],["C","Consolability"]], extra:"Each scored 0-2, total 0-10."},
  example:"Before heel-lance blood tests on a 34-week baby in a district SNCU, the physiotherapist helps the mother hold the baby skin-to-skin and the team uses NIPS before and after; scores drop from 6 to 2.",
  flags:["Pain out of proportion or night pain with weight loss (refer)","Signs of non-accidental injury","Pain behaviours in a non-verbal child that carers notice"],
  viva:[["Name a neonatal pain scale.","PIPP-R or NIPS."],["What does FLACC stand for?","Face, Legs, Activity, Cry, Consolability."],["Two non-drug pain relief methods in neonates?","Breastfeeding or skin-to-skin, and oral sucrose."]],
  refs:[{b:"rennie",ch:"Pain and analgesia in the newborn"},{b:"effgen",ch:"Pain in children"},{b:"iap",ch:"Pain management in children"}],
  keywords:"paediatric pain neonatal pain scales FLACC PIPP sucrose kangaroo",
  mcq:[["Which scale suits a 2-year-old?",["NRS","FLACC","VAS","McGill"],1,"FLACC is behavioural for young children."],["Each FLACC item is scored:",["0-1","0-2","0-5","0-10"],1,"Five items scored 0-2, total 0-10."]]
},
{
  id:"paeds-gait-development", title:"Development of gait in children", subject:"Paediatrics", region:"Lower limb", stages:"steps",
  aliases:["toddler gait","immature gait","mature gait","gait development","in-toeing children","Sutherland gait","walking development"],
  simple:"When toddlers first walk they keep their feet wide, arms up high and take short quick steps with flat feet. Over the next few years the gait becomes narrower, smoother and more adult-like, with heel strike and arm swing. Knowing what is normal at each age helps the physiotherapist spot real problems.",
  flow:["First steps about 12 months (range 9-18)","Immature gait: wide base, high guard arms, flat foot contact","By 2 years: heel strike and reciprocal arm swing appear","By 3-4 years: most adult features","By about 7 years: mature gait","Assess, compare with age norms, refer if abnormal"],
  exam:[
    {h:"Introduction", p:["Independent walking usually begins around 12 months; it is considered delayed if not walking by about 18 months and needs assessment.","Gait matures over the first 7 years as postural control, strength and limb length develop (Sutherland's classic work)."]},
    {h:"Features of immature gait (toddler)", p:["Wide base of support, hips abducted and externally rotated.","Arms in high guard, no reciprocal arm swing.","Short steps, high cadence, short single-limb stance time.","Flat foot or forefoot initial contact, little knee flexion in stance.","Frequent falls; speed varies."]},
    {h:"Maturation", p:["About 18 months to 2 years: arms lower, heel strike begins, reciprocal arm swing appears.","3 years: most adult kinematic patterns present; base narrows.","About 7 years: mature gait with adult-like single limb stance, step length relative to leg length and cadence; cadence continues to fall as legs lengthen.","Five determinants of mature gait (Sutherland): duration of single limb stance, walking velocity, cadence, step length and the ratio of pelvic span to ankle spread."]},
    {h:"Common normal variations", p:["Physiological genu varum (bow legs) up to about 2 years, then genu valgum peaking at 3-4 years, correcting by about 7 years.","Flexible flat foot in toddlers (fat pad, ligament laxity), usually improves.","In-toeing from femoral anteversion, tibial torsion or metatarsus adductus, usually resolves.","Toe walking is common briefly in early walkers; persistent toe walking after about 2-3 years needs assessment."]},
    {h:"Red flags and assessment", p:["Asymmetry, persistent toe walking, frequent falls with weakness, loss of walking, waddling with Gowers' sign, limp with pain or fever.","Observational gait analysis with video, Edinburgh visual gait score, timed tests and, where available, 3D gait laboratory analysis."]},
    {h:"Conclusion", p:["Knowing the timeline from immature to mature gait prevents overtreatment of normal variants and helps catch true pathology early."]}
  ],
  tip:"Draw two stick figures side by side: toddler (wide base, high guard arms, flat foot) and 7-year-old (narrow base, arm swing, heel strike).",
  evidence:[["Most in-toeing and flexible flat foot in young children","Resolve with growth without treatment","Moderate"],["Observational gait scales with video","Reasonable reliability for clinical use","Moderate"]],
  evidenceSource:"Sutherland et al. J Bone Joint Surg 1980; Effgen; Gallahue",
  outcomes:[["Edinburgh Visual Gait Score","Observational gait in CP"],["Temporal-spatial parameters","Cadence, step length, velocity"],["10 m walk test","Gait speed"]],
  recent:["Low-cost video and smartphone apps now allow basic gait parameter measurement in clinics without a gait laboratory."],
  mnemonic:{word:"WASH", items:[["W","Wide base"],["A","Arms high guard"],["S","Short quick steps"],["H","Heel strike absent (flat foot)"]], extra:"Toddlers WASH out of these by about 7 years."},
  example:"A worried mother in Vellore brings her 2-year-old with in-toeing and bow legs. Assessment shows symmetrical physiological genu varum and internal tibial torsion with normal milestones; the physiotherapist reassures and plans review in 6 months.",
  flags:["Not walking by 18 months","Persistent toe walking after 2-3 years","Gowers' sign or waddling","Asymmetrical gait, limp with pain or fever"],
  viva:[["At what age is gait mature?","About 7 years."],["Typical arm position in early walkers?","High guard."],["When does physiological genu valgum peak?","About 3-4 years."]],
  refs:[{b:"gallahue",ch:"Development of walking and running"},{b:"effgen",ch:"Gait and mobility in children"},{b:"illingworth",ch:"Development of walking"}],
  keywords:"gait development children toddler mature gait Sutherland in-toeing",
  mcq:[["Which is a feature of immature gait?",["Narrow base","Reciprocal arm swing","High guard arms","Heel strike"],2,"High guard arm position is typical of early walkers."],["Gait is adult-like by about:",["2 years","4 years","7 years","12 years"],2,"Sutherland: mature gait around 7 years."]]
},
{
  id:"jia", title:"Juvenile idiopathic arthritis: physiotherapy management", subject:"Paediatrics", region:"Joints", stages:"steps",
  aliases:["JIA","juvenile rheumatoid arthritis","juvenile chronic arthritis","Still's disease","oligoarthritis","polyarthritis children"],
  simple:"Juvenile idiopathic arthritis is long-lasting joint swelling in a child under 16 with no other cause. Joints get painful and stiff, especially in the morning, and children may stop running and playing. Medicines now control it well; physiotherapy keeps joints moving, muscles strong and children active and confident.",
  flow:["Diagnose: arthritis over 6 weeks, onset under 16 years","Classify (ILAR): oligo, poly, systemic and others","Assess joints, pain, function and growth","Flare: rest splints, gentle ROM, pain relief","Remission: strength, fitness, sport","Eye screening and school support"],
  exam:[
    {h:"Introduction", p:["JIA is the commonest chronic rheumatic disease in children: arthritis of unknown cause, starting before the 16th birthday and lasting at least 6 weeks, after other causes are excluded.","ILAR categories: systemic, oligoarticular (persistent or extended), polyarticular RF negative, polyarticular RF positive, psoriatic, enthesitis-related and undifferentiated."]},
    {h:"Clinical features", p:["Joint swelling, warmth, morning stiffness, limping, reluctance to play.","Oligoarthritis often affects knees and ankles; uveitis may be silent (regular eye screening needed, especially if ANA positive).","Systemic JIA: quotidian fever, evanescent salmon rash, lymphadenopathy, serositis; risk of macrophage activation syndrome.","Complications: contractures (knee flexion, hip flexion, wrist), leg length difference from local growth overgrowth, jaw (TMJ) involvement, muscle wasting, osteopenia, low fitness."]},
    {h:"Assessment", p:["Active and limited joint counts, ROM, leg length, muscle strength, gait, posture and fitness.","Pain (FPS-R or VAS), function: CHAQ (Childhood Health Assessment Questionnaire), JADAS for disease activity (team measure).","Participation in school and play."]},
    {h:"Management", p:["Medical (team): NSAIDs, intra-articular steroid injections, methotrexate, biologics (anti-TNF, IL-6 blockers).","Active phase: pain relief (cold, heat as tolerated), resting splints at night, gentle active ROM, isometric work, positioning to prevent contractures, hydrotherapy.","After injection: short relative rest of the joint as advised, then gradual return.","Inactive phase: progressive strengthening, aerobic fitness, balance, proprioception, gait re-education and orthoses (insoles, shoe raise).","Encourage sport and normal schooling; most children can join PE with adaptations."]},
    {h:"Conclusion", p:["Early medical control with active physiotherapy has transformed JIA. The goal is a child who moves, grows and plays normally."]}
  ],
  tip:"Draw a child with a swollen knee and ankle, labelled 'morning stiffness, limp', and a box 'eye check for uveitis'.",
  evidence:[["Exercise therapy in JIA","Safe; improves function and quality of life without worsening disease","Moderate"],["Aquatic and land-based exercise","Similar benefits for function","Moderate"]],
  evidenceSource:"Takken et al. Cochrane review of exercise in JIA; Kuntze et al. 2018 systematic review",
  outcomes:[["CHAQ","Function"],["Joint count and ROM","Disease effect on joints"],["6-minute walk test","Endurance"],["Pain FPS-R","Pain"]],
  recent:["Treat-to-target strategies with biologics aim for inactive disease, and the physiotherapist's role is shifting toward fitness and participation."],
  mnemonic:{word:"JOINT", items:[["J","Joint ROM daily"],["O","Orthoses and splints when active"],["I","Isometrics in flare"],["N","No missing school or sport"],["T","Train strength and fitness when quiet"]], extra:"Protect the JOINT, grow the child."},
  example:"A 6-year-old girl in Pondicherry with oligoarticular JIA has a swollen right knee and a 15-degree flexion contracture after a joint injection. A night extension splint, quadriceps work and cycling play restore full extension in 6 weeks.",
  flags:["Fever with rash and serositis (systemic JIA)","Painful red eye or blurred vision","Night pain, weight loss or single painful bone (exclude malignancy or infection)"],
  viva:[["Minimum duration for JIA diagnosis?","6 weeks."],["Which subtype has highest uveitis risk?","Oligoarticular, ANA positive, young girls."],["Is exercise safe in JIA?","Yes; it improves function without increasing disease activity."]],
  refs:[{b:"iap",ch:"Rheumatology: juvenile idiopathic arthritis"},{b:"effgen",ch:"Juvenile idiopathic arthritis"},{b:"campbell",ch:"Juvenile idiopathic arthritis"},{b:"nelson",ch:"Juvenile idiopathic arthritis"}],
  keywords:"juvenile idiopathic arthritis JIA physiotherapy children arthritis",
  mcq:[["JIA onset must be before:",["5 years","10 years","16 years","21 years"],2,"Before the 16th birthday."],["A silent complication needing screening:",["Uveitis","Otitis","Cataract only","Glaucoma only"],0,"Anterior uveitis can be asymptomatic."]]
},
{
  id:"paeds-respiratory-physio", title:"Paediatric respiratory physiotherapy: bronchiolitis, pneumonia and airway clearance in children", subject:"Paediatrics", region:"Chest", stages:"steps",
  aliases:["bronchiolitis","paediatric chest physiotherapy","children airway clearance","pneumonia children","PICU physiotherapy","cystic fibrosis children","infant chest physio"],
  simple:"Children's airways are small and their chest walls soft, so they tire and block up quickly. Physiotherapy helps only when there are secretions the child cannot clear or a part of the lung has collapsed. For common bronchiolitis in babies, routine chest physiotherapy does not help; good positioning, feeding and oxygen support do.",
  flow:["Know the child's anatomy and physiology differences","Assess: work of breathing, SpO2, auscultation, X-ray","Decide: is there a treatable problem (secretions, collapse)?","Choose age-appropriate techniques","Monitor during and after; stop if unstable","Teach family; avoid routine treatment in bronchiolitis"],
  exam:[
    {h:"Introduction: why children differ", p:["Smaller airways (resistance rises sharply with a little swelling), fewer collateral channels, compliant chest wall, horizontal ribs and a diaphragm-dependent breathing pattern.","Infants are preferential nasal breathers; higher metabolic rate and oxygen consumption; they fatigue quickly.","Ventilation in infants may go preferentially to the upper lung in side lying, unlike adults."]},
    {h:"Conditions", p:["Bronchiolitis (usually RSV, under 2 years): wheeze, crackles, feeding difficulty.","Pneumonia, lobar collapse, aspiration, post-operative chest problems.","Chronic: cystic fibrosis, primary ciliary dyskinesia, bronchiectasis, neuromuscular weakness (SMA, DMD).","Asthma: education, breathing control and exercise; not airway clearance unless secretions."]},
    {h:"Assessment", p:["Work of breathing: rate, recession, nasal flaring, grunting, head bobbing, see-saw breathing.","SpO2, heart rate, temperature, feeding, hydration, chest X-ray and auscultation.","Cough effectiveness and secretion type."]},
    {h:"Techniques by age", p:["Infants: positioning (prone in monitored settings, head up), modified postural drainage (no head-down in infants with reflux or raised ICP), chest percussion and vibrations over a cloth, assisted cough, nasopharyngeal suction only when needed and per protocol.","Children: active cycle of breathing techniques (from about 3-4 years with play), autogenic drainage (older children), PEP and oscillating PEP devices, bubble PEP in young children, huffing games, exercise as airway clearance.","Neuromuscular: lung volume recruitment, assisted cough, mechanical insufflation-exsufflation."]},
    {h:"Bronchiolitis: what the evidence says", p:["Routine chest physiotherapy (vibration, percussion, slow passive expiration) does not shorten illness or hospital stay in otherwise healthy infants and can distress them.","Supportive care: oxygen if saturation low, nasal suction for feeding, hydration, high-flow nasal cannula when needed.","Physiotherapy may be considered for children with co-existing conditions (neuromuscular disease, chronic lung disease) or with lobar collapse."]},
    {h:"Conclusion", p:["Treat the problem, not the diagnosis. Thoughtful, age-specific and evidence-based chest physiotherapy helps children with secretion retention, while unnecessary treatment is avoided."]}
  ],
  tip:"Draw a child versus adult chest: small airways, soft ribs, horizontal ribs, big diaphragm role, with a note 'no routine chest physio in bronchiolitis'.",
  evidence:[["Chest physiotherapy in acute bronchiolitis","No improvement in severity or length of stay","High"],["Airway clearance in cystic fibrosis","Short-term improvement in mucus transport; no technique clearly superior","Moderate"],["Mechanical insufflation-exsufflation in neuromuscular disease","Improves cough peak flow","Moderate"]],
  evidenceSource:"Roque-Figuls et al. Cochrane 2023 on chest physiotherapy for bronchiolitis; NICE NG9 bronchiolitis; McIlwaine et al. Cochrane on CF airway clearance",
  outcomes:[["Respiratory rate, SpO2","Work of breathing and oxygenation"],["Bronchiolitis severity score","Clinical severity"],["Peak cough flow","Cough strength in neuromuscular disease"]],
  recent:["NICE bronchiolitis guideline (NG9, updated 2021) advises against chest physiotherapy in children without relevant comorbidities."],
  mnemonic:{word:"SMALL", items:[["S","Small airways block fast"],["M","Monitor SpO2 and HR"],["A","Age-appropriate technique"],["L","Look for a real indication"],["L","Leave routine bronchiolitis alone"]], extra:"Small chests need smart care."},
  example:"An 8-month-old with RSV bronchiolitis in a Salem hospital has crackles but feeds with nasal saline and suction and keeps saturation above 92 percent on low-flow oxygen. The physiotherapist advises positioning and family teaching but no chest percussion.",
  flags:["Apnoea, exhaustion, falling respiratory rate","SpO2 persistently below 90-92 percent","Severe recession, grunting, poor feeding, dehydration"],
  viva:[["Is chest physiotherapy recommended in bronchiolitis?","Not routinely in otherwise healthy infants."],["Name an airway clearance device for children.","Oscillating PEP or bubble PEP."],["Why do infants fatigue quickly?","High metabolic demand, compliant chest wall and small airways."]],
  refs:[{b:"rennie",ch:"Respiratory disorders in the newborn"},{b:"iap",ch:"Respiratory system: bronchiolitis and pneumonia"},{b:"effgen",ch:"Cardiopulmonary conditions in children"},{b:"frownfelter",ch:"Paediatric cardiopulmonary physical therapy"}],
  keywords:"paediatric respiratory physiotherapy bronchiolitis airway clearance children",
  mcq:[["Most common cause of bronchiolitis:",["RSV","Pneumococcus","TB","Asthma"],0,"Respiratory syncytial virus."],["Head-down drainage should be avoided in infants with:",["Reflux","Flat feet","Myopia","Eczema"],0,"Head-down tilt worsens gastro-oesophageal reflux."]]
},
{
  id:"gmfcs", title:"Classifying function in cerebral palsy: GMFCS, MACS and CFCS", subject:"Paediatrics", region:"Whole child", stages:"steps",
  aliases:["GMFCS","gross motor function classification system","MACS","manual ability classification","CFCS","EDACS","motor growth curves","CP classification"],
  simple:"Children with cerebral palsy differ a lot in how they move, use their hands and communicate. Simple five-level systems describe what a child usually does in daily life: GMFCS for walking and moving, MACS for hand use and CFCS for communication. They help families and teams talk the same language and predict future gross motor function.",
  flow:["Observe usual performance, not best capacity","Use age band (GMFCS E&R: under 2, 2-4, 4-6, 6-12, 12-18)","Choose level I to V","Add MACS, CFCS and EDACS","Use motor growth curves to predict","Plan goals, equipment and services by level"],
  exam:[
    {h:"Introduction", p:["CP is classified by motor type (spastic, dyskinetic, ataxic), distribution (unilateral, bilateral) and, most usefully for planning, by functional level.","The Gross Motor Function Classification System (GMFCS, Palisano 1997; expanded and revised 2007) is reliable and stable over time."]},
    {h:"GMFCS levels (6-12 years band)", p:["Level I: walks without limitations; runs and jumps but speed, balance and coordination are reduced.","Level II: walks with limitations; difficulty on uneven ground, slopes, crowds; uses rails on stairs; minimal ability to run or jump.","Level III: walks using a hand-held mobility device indoors; uses a wheelchair for longer distances.","Level IV: self-mobility with limitations; may use powered mobility; transported in a manual wheelchair.","Level V: transported in a manual wheelchair in all settings; limited head and trunk control."]},
    {h:"MACS, CFCS and EDACS", p:["MACS (4-18 years; Mini-MACS 1-4 years): handling objects in daily activities, levels I-V.","CFCS: everyday communication effectiveness with familiar and unfamiliar partners, levels I-V.","EDACS: eating and drinking ability, levels I-V, with assistance level."]},
    {h:"Motor growth curves and prognosis", p:["Rosenbaum's GMFM-66 motor growth curves show that children at each GMFCS level reach about 90 percent of their gross motor potential by about age 5 (level I) to about 3 years (level V).","Children at levels III-V may lose some function in adolescence, so preventing decline is a goal.","Hip surveillance is linked to level: the higher the level, the higher the risk of hip displacement (regular hip X-rays for levels III-V)."]},
    {h:"Clinical use", p:["Set realistic, family-centred goals, plan equipment (walkers at level III, powered mobility at level IV), estimate service needs and select outcome measures.","Use in research and audit to compare like with like."]},
    {h:"Conclusion", p:["GMFCS with MACS, CFCS and EDACS gives a full, functional picture of a child with CP and guides prognosis, hip surveillance and planning."]}
  ],
  tip:"Draw five stick figures for GMFCS I-V: running, walking with rail, walker, powered chair, transported chair.",
  evidence:[["GMFCS reliability","Excellent inter-rater reliability; stable over time","High"],["Hip surveillance by GMFCS level","Earlier detection of hip displacement","High"]],
  evidenceSource:"Palisano et al. Dev Med Child Neurol 1997 and 2008; Rosenbaum et al. JAMA 2002; Eliasson et al. 2006 (MACS)",
  outcomes:[["GMFCS E&R","Gross motor function level"],["MACS","Manual ability"],["CFCS","Communication"],["GMFM-66","Change in gross motor function"]],
  recent:["CP hip surveillance programmes (for example CPUP-style) are expanding and use GMFCS level to set X-ray frequency."],
  mnemonic:{word:"WHO EATS TALKS", items:[["W","Walking: GMFCS"],["H","Hands: MACS"],["T","Talking: CFCS"],["E","Eating: EDACS"]], extra:"Four functions, five levels each."},
  example:"A 7-year-old boy with spastic diplegia in Erode walks at school with a posterior walker and uses a wheelchair on trips: GMFCS III. Goals focus on transfers and walker skills, and hip X-rays are planned yearly.",
  flags:["Hip migration percentage rising (above about 30 percent: refer)","Loss of gross motor function","Scoliosis progression in levels IV-V"],
  viva:[["What does GMFCS describe?","Usual gross motor performance in daily life, levels I-V."],["Who developed GMFCS?","Palisano and colleagues, 1997."],["At what age do most children reach their motor plateau?","Around 3-5 years depending on level."]],
  refs:[{b:"effgen",ch:"Cerebral palsy: classification and prognosis"},{b:"campbell",ch:"Cerebral palsy"},{c:"Palisano RJ, Rosenbaum P, Bartlett D, Livingston MH. Content validity of the expanded and revised Gross Motor Function Classification System. Dev Med Child Neurol. 2008;50(10):744-750.",q:"Palisano GMFCS expanded revised 2008"}],
  keywords:"GMFCS MACS CFCS EDACS cerebral palsy classification motor growth curves",
  mcq:[["A child who walks with a walker indoors and uses a wheelchair outdoors is GMFCS:",["I","II","III","V"],2,"Hand-held mobility device: level III."],["MACS classifies:",["Walking","Hand use with objects","Speech","Vision"],1,"Manual Ability Classification System."]]
}
]);
